"""Summarize mailtodo letters without modifying the input tree."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re


_NAME = re.compile(r"^[0-9]{8}T[0-9]{4}[-_]")
_RESOLVED = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}


def read_letter(path, now):
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeError):
        return None, "no_frontmatter"
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"

    fields = {}
    for line in lines[1:end]:
        key, separator, value = line.partition(": ")
        if separator:
            fields[key] = value
    if any(not fields.get(key) for key in ("id", "from", "to", "status")):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields.get("at", ""))
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)

    if not _NAME.match(path.name):
        return None, "bad_name"
    try:
        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    fields["at"] = at
    return fields, None


def summarize(root, now):
    boxes = {}
    files = []
    for box in root.iterdir():
        if box.name.startswith(".") or box.is_symlink() or not box.is_dir():
            continue
        inbox = box / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[box.name] = {"inbox": {}, "done": 0}
        for where, directory in (("inbox", inbox), ("done", inbox / "done")):
            if directory.is_symlink() or not directory.is_dir():
                continue
            for path in directory.iterdir():
                if (path.name.startswith(".") or path.suffix != ".md"
                        or path.is_symlink() or not path.is_file()):
                    continue
                files.append((path.relative_to(root).as_posix(), box.name, where, path))

    bad = []
    valid = []
    ids = set()
    for relative, box, where, path in sorted(files):
        letter, why = read_letter(path, now)
        if why is None and letter["id"] in ids:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        ids.add(letter["id"])
        valid.append((letter, box, where))
        if where == "done":
            boxes[box]["done"] += 1
        else:
            counts = boxes[box]["inbox"]
            status = letter["status"]
            counts[status] = counts.get(status, 0) + 1

    resolved = {letter.get("re") for letter, _, _ in valid
                if letter["status"] in _RESOLVED and letter.get("re")}
    open_letters = []
    for letter, _, where in valid:
        if letter["status"] != "REQUEST" or letter["id"] in resolved:
            continue
        open_letters.append({
            "id": letter["id"], "from": letter["from"], "to": letter["to"],
            "where": where, "age_min": (now - letter["at"]) // timedelta(minutes=1),
        })
    open_letters.sort(key=lambda item: (item["to"], item["id"]))
    ordered_boxes = {name: {"inbox": dict(sorted(boxes[name]["inbox"].items())),
                            "done": boxes[name]["done"]} for name in sorted(boxes)}
    bad.sort(key=lambda item: (item["file"], item["why"]))
    return {"v": 1, "open": open_letters, "boxes": ordered_boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailtodo summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
        if now.tzinfo is None:
            raise ValueError("timezone required")
    except ValueError:
        parser.error("--now must be a valid timezone-aware ISO timestamp")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
